'use strict';
const STORY_CHAPTERS=[
 {title:'I · Ostatni wędrowiec',speaker:'Mira, zwiadowczyni',text:'Na starym trakcie spotykasz Mirę. „Dawna osada spłonęła, ale dolina wciąż daje schronienie. Zbierz drewno. Zbudujemy nowy dom”.',goal:'Zetnij 5 drzew.',progress:()=>Math.min(5,state.chopped)+'/5 drzew',ready:()=>state.chopped>=5,reward:20},
 {title:'II · Nad spokojną rzeką',speaker:'Mira',text:'„Słyszysz wodę? Rzeka napędzi młyny i nakarmi pola. Wybierz miejsce, w którym ludzie znów poczują się bezpiecznie”.',goal:'Załóż osadę nad rzeką przyciskiem ⚑.',progress:()=>state.settled?'Osada założona':'Szukaj rzeki na wschodzie',ready:()=>!!state.settled,reward:30},
 {title:'III · Światła w oknach',speaker:'Antek, cieśla',text:'Do ogniska podchodzi cieśla z rodziną. „Postaw dwa domy. Pomogę zbudować miejsce, do którego inni zechcą wracać”.',goal:'Zbuduj 2 domy.',progress:()=>Math.min(2,ownCount('dom'))+'/2 domy',ready:()=>ownCount('dom')>=2,reward:40},
 {title:'IV · Chleb i drewno',speaker:'Basia, rolniczka',text:'„Same dachy nie wystarczą. Drwal potrzebuje chaty, a rolnik pola. Połącz je ścieżkami i zostaw otwarte przejścia”.',goal:'Zbuduj chatę drwala i pole. Niech przynajmniej 2 mieszkańców podejmie pracę.',progress:()=>ownCount('drwal')+' chat drwala · '+ownCount('pole')+' pól · '+residents.filter(r=>r.job).length+' zatrudnionych',ready:()=>ownCount('drwal')>=1&&ownCount('pole')>=1&&residents.filter(r=>r.job).length>=2,reward:50},
 {title:'V · Zanim przyjdzie mróz',speaker:'Basia',text:'Nad doliną przelatują ostatnie żurawie. „Zróbmy zapasy, zanim śnieg przykryje pola. Skład ochroni nas przed brakiem miejsca”.',goal:'Zbuduj skład i zgromadź 100 żywności oraz 60 drewna. Zapasy pozostają Twoje.',progress:()=>ownCount('sklad')+' składów · '+Math.floor(state.food)+'/100 żywności · '+Math.floor(state.wood)+'/60 drewna',ready:()=>ownCount('sklad')>=1&&state.food>=100&&state.wood>=60,reward:60},
 {title:'VI · Dym na wzgórzach',speaker:'Mira',text:'„Na wzgórzach widziałam obcych. Zbuduj wieżę i biuro werbunkowe. Potrzebujemy czterech wyszkolonych obrońców. Dopiero wtedy damy sygnał, że jesteśmy gotowi”.',goal:'Zbuduj wieżę i biuro werbunkowe. Wyszkol 4 żołnierzy pozostających w garnizonie.',progress:()=>ownCount('wieza')+' wież · '+ownCount('werbunek')+' biur · '+state.war.soldiers+'/4 żołnierzy',ready:()=>ownCount('wieza')>=1&&ownCount('werbunek')>=1&&state.war.soldiers>=4,reward:70},
 {title:'VII · Obrońcy doliny',speaker:'Mira',text:'„Nadszedł czas. Gdy będziesz gotowy, zapal ognisko sygnałowe. Najeźdźcy podejdą do osady. Nie pozwól im odebrać nam nowego domu”.',goal:'Uruchom finałowy najazd i obroń osadę. Po porażce możesz spróbować ponownie.',progress:()=>storyState()?.battle==='won'?'Osada obroniona!':storyState()?.battle==='active'?'Najazd trwa — broń osady':storyState()?.battle==='lost'?'Odbuduj obronę i spróbuj ponownie':'Najazd czeka na Twój sygnał',ready:()=>storyState()?.battle==='won',reward:150}
];
function storyState(){return state.story||null}
function startStory(){if(!state.story)state.story={chapter:0,active:true,battle:'idle',attempt:0,history:[]};else state.story.active=true;storySignature='';save();renderStory();say('Rozpoczyna się opowieść o Zielonej Dolinie.')}
function storyAdvance(){const s=storyState(),chapter=s&&STORY_CHAPTERS[s.chapter];if(!s?.active||!chapter||!chapter.ready())return false;s.history.push(chapter.title);s.chapter++;state.gold+=chapter.reward;if(s.chapter===STORY_CHAPTERS.length){s.active=false;s.completed=true;s.ending='Mira staje przy bramie. „To już nie przystanek wędrowców. To nasz dom”. W dolinie zapalają się światła, a mieszkańcy świętują. Zdobywasz tytuł Opiekuna Doliny. Swobodna gra trwa dalej.'}save();ui();storySignature='';renderStory();return true}
function launchStoryRaid(){const s=storyState();if(!s?.active||s.chapter!==6||s.battle==='active'||s.battle==='won')return false;if(state.war.raids.length){say('Najpierw zakończ obecny najazd.');return false}if(!STORY_CHAPTERS[5].ready()){say('Przygotuj wieżę, biuro i 4 żołnierzy w garnizonie.');return false}const o=villageOrigin();let from=null;for(let radius=12;radius<=18&&!from;radius++)for(const [dx,dy] of [[-radius,0],[0,-radius],[0,radius],[radius,0]]){const x=o.x+dx,y=o.y+dy;if(terrain(x,y)==='grass'&&!building(x,y)&&!foreignBuilding(x,y)){from={x,y};break}}if(!from){say('Brak miejsca dla najazdu. Odsłoń teren wokół osady.');return false}const approach=raidApproach(from,o);s.attempt++;s.raidId='story-raid-'+s.attempt;s.battle='active';state.war.raids.push({townId:s.raidId,...approach,hostile:true,naval:false,power:18,story:true});for(const p of approach.route)seen.add(tileKey(Math.floor(p.x),Math.floor(p.y)));save();storySignature='';renderStory();say('Mira: Najeźdźcy nadchodzą! Broń doliny!');return true}
const storyResolveRaid=resolveRaid;
resolveRaid=function(r){const s=storyState();if(r.story&&s?.raidId===r.townId)s.battle=defensePower()>=r.power?'won':'lost';storyResolveRaid(r)};
const storyUpdateWar=updateWar;
updateWar=function(dt){const s=storyState(),raid=s?.battle==='active'&&state.war.raids.find(r=>r.townId===s.raidId);storyUpdateWar(dt);if(raid&&s.battle==='active'&&!state.war.raids.includes(raid)){s.battle=raid.power<=0?'won':'lost';save();storySignature='';say(s.battle==='won'?'Mira: Udało się! Dolina jest bezpieczna.':'Mira: Odbudujemy obronę i spróbujemy jeszcze raz.')}};
let storySignature='';
function renderStory(){const panel=$('storyPanel');if(panel.classList.contains('hidden'))return;const s=storyState(),ch=s&&STORY_CHAPTERS[s.chapter],signature=JSON.stringify([s,ch?.progress(),ch?.ready(),state.war.raids.length]);if(signature===storySignature)return;storySignature=signature;$('storyContent').innerHTML=!s?'<p class="story-intro">DZIEDZICTWO ZIELONEJ DOLINY</p><h2>Dom pośród dziczy</h2><p>Siedem rozdziałów o odbudowie osady, przyjaźni i obronie nowego domu. Mira, Antek i Basia poprowadzą Cię przez historię.</p><p>Możesz zacząć w obecnej wiosce. Istniejące budynki liczą się do zadań. Postęp fabuły zapisuje się wraz z osadą.</p><button data-story="start">Rozpocznij opowieść</button>':s.completed?'<p class="story-intro">OPOWIEŚĆ UKOŃCZONA · 7/7</p><h2>Opiekun Doliny</h2><p>'+s.ending+'</p><p>Zdobyte nagrody: 270 monet + 150 monet za finał.</p>':`<small>ROZDZIAŁ ${s.chapter+1}/7 · ${s.active?'FABUŁA AKTYWNA':'FABUŁA WSTRZYMANA'}</small><h2>${ch.title}</h2><p class="story-speaker">${ch.speaker}</p><p class="story-dialogue">${ch.text}</p><h3>Twoje zadanie</h3><p>${ch.goal}</p><p class="story-progress">${ch.progress()}</p><p>Nagroda: ${ch.reward} monet</p>${s.chapter===6?'<button data-story="raid" '+(!s.active||['active','won'].includes(s.battle)?'disabled':'')+'>Zapal ognisko · rozpocznij najazd</button>':''}<button data-story="next" ${!s.active||!ch.ready()?'disabled':''}>${s.chapter===6?'Zakończ opowieść':'Odbierz nagrodę i czytaj dalej'}</button><button data-story="toggle">${s.active?'Wstrzymaj fabułę':'Wznów fabułę'}</button><p><small>Wstrzymanie fabuły nie zatrzymuje świata ani rozpoczętego najazdu. Spacja zatrzymuje całą grę.</small></p>`;if(s?.history.length)$('storyContent').innerHTML+='<details><summary>Kronika rozdziałów</summary>'+s.history.map(t=>'<p>✓ '+t+'</p>').join('')+'</details>'}
function openStory(){$('storyPanel').classList.remove('hidden');storySignature='';renderStory()}
$('storyOpen').onclick=openStory;$('storyClose').onclick=()=>$('storyPanel').classList.add('hidden');$('storyContent').onclick=e=>{const action=e.target.closest('[data-story]')?.dataset.story;if(action==='start')startStory();if(action==='next')storyAdvance();if(action==='raid')launchStoryRaid();if(action==='toggle'){const s=storyState();s.active=!s.active;save();storySignature='';renderStory()}};
const storyUI=ui;ui=function(){storyUI();renderStory()};window.addEventListener('keydown',e=>{if(e.key==='Escape')$('storyPanel').classList.add('hidden')});
